_PLAYER_GD = '''\
extends CharacterBody2D
## M0 player — move, jump, fail if you fall. Extend; do not replace with Phaser.

const SPEED := 240.0
const JUMP_VELOCITY := -420.0
const GRAVITY := 980.0

func _ready() -> void:
	var pit := get_parent().get_node_or_null("Pit")
	if pit and not pit.body_entered.is_connected(_on_pit):
		pit.body_entered.connect(_on_pit)

func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += GRAVITY * delta
	var dir := Input.get_axis("ui_left", "ui_right")
	velocity.x = dir * SPEED
	if Input.is_action_just_pressed("ui_accept") and is_on_floor():
		velocity.y = JUMP_VELOCITY
	move_and_slide()
	if global_position.y > 1200.0:
		Game.fail("fell")

func _on_pit(body: Node2D) -> void:
	if body == self:
		Game.fail("pit")
'''

_GAME_GD = '''\
extends Node
## Autoload Game — score, fail, reset. UI reads this; gameplay does not duplicate it.

signal failed(reason: String)
signal scored(total: int)

var score: int = 0
var is_failed: bool = false

func add_score(amount: int = 1) -> void:
	if is_failed:
		return
	score += amount
	scored.emit(score)

func fail(reason: String = "fail") -> void:
	if is_failed:
		return
	is_failed = true
	failed.emit(reason)

func reset() -> void:
	score = 0
	is_failed = false
	get_tree().reload_current_scene()

func _unhandled_input(event: InputEvent) -> void:
	if is_failed and event.is_action_pressed("ui_accept"):
		reset()
'''

